-- CAP Companion App — migration 009: QR scan codes + Encyclopedia stub
--
-- Adds word-based scannable codes for park signage (e.g. "brave-otter"),
-- usable for both the existing Scavenger Hunt characters and a brand new
-- minimal Encyclopedia stub table. scannable_codes is a real polymorphic
-- association -- exactly one of hunt_character_id / encyclopedia_entry_id is
-- set, enforced by a check constraint -- rather than an untyped
-- (type, target_id) pair, so referential integrity (cascade on delete, FK
-- validation) stays intact for whichever side is used.
--
-- Codes are generated by backend/app/services/scan_codes.py's curated word
-- lists (two common, easy-to-spell English words joined by a hyphen), picked
-- by hand for this seed so specific codes can be printed on physical signage
-- ahead of time. Lookup normalizes case/whitespace (see scan_codes.normalize_code
-- and app/services/scan.py) so "Brave Otter" / "brave-otter" / "  brave-otter  "
-- all resolve the same code -- the stored value itself is always the
-- canonical lowercase-hyphenated form.
--
-- encyclopedia_entries is intentionally minimal (id, animal_name, status) --
-- just enough to be a real scan target with a "Coming soon" page. The full
-- card-based Encyclopedia feature (Plan.md 2.5/5) is a later sprint, once
-- real animal photos/facts exist.
--
-- Per the project's established gotcha (seed.sql edits don't reach the live
-- DB -- see migrations 004-008's headers), this migration is what actually
-- applies the change to the live database; seed.sql and schema.sql are
-- updated separately (seed.sql for fresh-install data, schema.sql for a
-- fresh project's baseline).
--
-- Run this in the Supabase SQL editor against the live project.
-- Safe to run more than once: table/index creates are guarded, and every
-- insert is guarded by ON CONFLICT DO NOTHING (encyclopedia_entries.animal_name,
-- scannable_codes.code).

-- ---------------------------------------------------------------------------
-- tables
-- ---------------------------------------------------------------------------
create table if not exists encyclopedia_entries (
    id          uuid primary key default gen_random_uuid(),
    animal_name text not null unique,
    status      text not null default 'placeholder' check (status in ('placeholder', 'published')),
    created_at  timestamptz not null default now()
);

create table if not exists scannable_codes (
    id                    uuid primary key default gen_random_uuid(),
    code                  text not null unique,
    hunt_character_id     uuid references hunt_characters(id) on delete cascade,
    encyclopedia_entry_id uuid references encyclopedia_entries(id) on delete cascade,
    created_at            timestamptz not null default now(),
    constraint scannable_codes_exactly_one_target check (
        (hunt_character_id is not null)::int + (encyclopedia_entry_id is not null)::int = 1
    )
);

create index if not exists scannable_codes_hunt_character_id_idx on scannable_codes(hunt_character_id);
create index if not exists scannable_codes_encyclopedia_entry_id_idx on scannable_codes(encyclopedia_entry_id);

-- ---------------------------------------------------------------------------
-- encyclopedia_entries (5 launch-scannable stubs, distinct from the 5 hunt
-- characters so a scanned sign never doubles as a hunt spoiler)
-- ---------------------------------------------------------------------------
insert into encyclopedia_entries (animal_name, status) values
    ('Red Panda', 'placeholder'),
    ('Flamingo',  'placeholder'),
    ('Meerkat',   'placeholder'),
    ('Otter',     'placeholder'),
    ('Peacock',   'placeholder')
on conflict (animal_name) do nothing;

-- ---------------------------------------------------------------------------
-- scannable_codes -- one per hunt character (5) + one per encyclopedia entry (5)
-- ---------------------------------------------------------------------------
insert into scannable_codes (code, hunt_character_id)
select v.code, c.id
from hunt_characters c
join (values
    ('brave-otter',  'Kangaroo'),
    ('happy-panda',  'Pig'),
    ('calm-turtle',  'Capybara'),
    ('quick-falcon', 'Snake'),
    ('sleepy-koala', 'Sloth')
) as v(code, name) on v.name = c.name
on conflict (code) do nothing;

insert into scannable_codes (code, encyclopedia_entry_id)
select v.code, e.id
from encyclopedia_entries e
join (values
    ('jolly-zebra',   'Red Panda'),
    ('silly-badger',  'Flamingo'),
    ('sunny-beaver',  'Meerkat'),
    ('lucky-giraffe', 'Otter'),
    ('proud-eagle',   'Peacock')
) as v(code, animal_name) on v.animal_name = e.animal_name
on conflict (code) do nothing;
